package handlers

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"net/http"

	"github.com/gin-gonic/gin"
)

func computeSHA256Hash(text string) string {
	hash := sha256.Sum256([]byte(text))
	return hex.EncodeToString(hash[:])
}

// PUT /objects/{bucket}/{objectID}
// this is a terrible pattern since users are not supposed to decide the objectID
// In a real-world scenario, the objectID should be generated by the server and returned to the user.

func (gh *GenericHTTPHandler) PutObject(ctx *gin.Context) {
	var req ApiRequestGetPutDelete

	if err := ctx.ShouldBindUri(&req); err != nil {
		ctx.JSON(http.StatusBadRequest, ResponseTemplatePutDelete{
			Bucket:   req.Bucket,
			ObjectID: req.ObjectID,
			Message:  "Invalid request",
		})
		return
	}

	var reqBody ApiRequestPutBody
	if err := ctx.ShouldBindJSON(&reqBody); err != nil {
		ctx.JSON(http.StatusBadRequest, ResponseTemplatePutDelete{
			Bucket:   req.Bucket,
			ObjectID: req.ObjectID,
			Message:  "Invalid request body",
		})
		return
	}

	bucket := req.Bucket
	objectID := req.ObjectID
	content := reqBody.Content

	sha256_hash := computeSHA256Hash(content)

	// first of all let's check if the bucket exists
	bucketObj, err := gh.DBHandler.GetBucketByID(ctx, bucket)

	if err != nil && err != sql.ErrNoRows {
		ctx.JSON(http.StatusInternalServerError, ResponseTemplatePutDelete{
			Bucket:   bucket,
			ObjectID: objectID,
			Message:  "Failed to check bucket existence",
		})
		return
	}

	// if the bucket does not exist, create it
	if bucketObj == nil {
		err = gh.DBHandler.InsertBucket(ctx, bucket)

		if err != nil {
			ctx.JSON(http.StatusInternalServerError, ResponseTemplatePutDelete{
				Bucket:   bucket,
				ObjectID: objectID,
				Message:  "Failed to create bucket",
			})
			return
		}
	}

	// check if the object already exists

	objectExists, err := gh.DBHandler.CheckObjectExistance(ctx, bucket, objectID, sha256_hash)

	if err != nil {
		ctx.JSON(http.StatusInternalServerError, ResponseTemplatePutDelete{
			Bucket:   bucket,
			ObjectID: objectID,
			Message:  "Failed to check object existence",
		})
		return
	}

	if objectExists {
		ctx.JSON(http.StatusConflict, ResponseTemplatePutDelete{
			Bucket:   bucket,
			ObjectID: objectID,
			Message:  "An object with the same content already exists in the bucket",
		})
		return
	}

	// if the object does not exist, store it in the database

	err = gh.DBHandler.InsertObject(ctx, objectID, bucket, content, sha256_hash)

	if err != nil {
		ctx.JSON(http.StatusInternalServerError, ResponseTemplatePutDelete{
			Bucket:   bucket,
			ObjectID: objectID,
			Message:  "Failed to store object",
		})
		return
	}

	ctx.JSON(http.StatusCreated, ResponseTemplatePutDelete{
		Bucket:   bucket,
		ObjectID: objectID,
		Message:  "Object stored successfully",
	})
}
